from __future__ annotations
import math

class _Tokenizer:
    def __init__(self, expr: str) -> None:
        self.expr = expr
        self.pos = 0
        self.length = len(expr)
        self.current_token: str | None = None
        self.next_token()

    def next_token(self) -> None:
        while self.pos < self.length and self.expr[self.pos].isspace():
            self.pos += 1

        if self.pos >= self.length:
            self.current_token = None
            return

        c = self.expr[self.pos]
        if c in "+-*/^()":
            self.current_token = c
            self.pos += 1
        elif c.isdigit() or c == '.':
            start = self.pos
            has_dot = False
            while self.pos < self.length:
                ch = self.expr[self.pos]
                if ch.isdigit():
                    self.pos += 1
                elif ch == '.' and not has_dot:
                    has_dot = True
                    self.pos += 1
                else:
                    break

            # Check for exponent part (scientific notation like 1e10)
            if self.pos < self.length and self.expr[self.pos] in 'eE':
                self.pos += 1
                if self.pos < self.length and self.expr[self.pos] in '+-':
                    self.pos += 1
                has_digits = False
                while self.pos < self.length and self.expr[self.pos].isdigit():
                    has_digits = True
                    self.pos += 1
                if not has_digits:
                    raise ValueError("Malformed scientific notation")

            self.current_token = self.expr[start:self.pos]
        else:
            raise ValueError(f"Invalid character: {c}")

def evaluate(expr: str) -> float:
    tokenizer = _Tokenizer(expr)

    def parse_expr() -> float:
        val = parse_term()
        while tokenizer.current_token in ('+', '-'):
            op = tokenizer.current_token
            tokenizer.next_token()
            right = parse_term()
            if op == '+':
                val = val + right
            else:
                val = val - right
        return val

    def parse_term() -> float:
        val = parse_factor()
        while tokenizer.current_token in ('*', '/'):
            op = tokenizer.current_token
            tokenizer.next_token()
            right = parse_factor()
            if op == '*':
                val = val * right
            else:
                val = val / right
        return val

    def parse_factor() -> float:
        # Unary operators
        if tokenizer.current_token in ('+', '-'):
            op = tokenizer.current_token
            tokenizer.next_token()
            val = parse_power()
            return -val if op == '-' else val
        return parse_power()

    def parse_power() -> float:
        # ^ is right-associative and binds tighter than unary minus/plus.
        # However, an exponent may itself start with a minus (e.g., 2^-1).
        # We parse a base (which can be primary or unary), then optionally ^ and another power.
        val = parse_primary()
        if tokenizer.current_token == '^':
            tokenizer.next_token()
            right = parse_factor()  # Right-associative: recursively parse power/factor
            val = val ** right
        return val

    def parse_primary() -> float:
        tok = tokenizer.current_token
        if tok is None:
            raise ValueError("Unexpected end of expression")

        if tok == '(':
            tokenizer.next_token()
            val = parse_expr()
            if tokenizer.current_token != ')':
                raise ValueError("Expected closing parenthesis")
            tokenizer.next_token()
            return val

        # Try to parse as number
        try:
            val = float(tok)
            tokenizer.next_token()
            return val
        except ValueError:
            raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if tokenizer.current_token is not None:
        raise ValueError("Unexpected trailing tokens")
    return float(result)
